#define orbs 20.

void main() {
  vec2 uv = k_uv();
  uv *= zoom;
  float stream = stream / 1.2;
  float dist = length(uv);
  uv *= k_rotate2d(stream/15.);
  uv = k_kale(uv, vec2(center), sides);
  uv *= k_rotate2d(stream/5.);
  for (float i = 0.; i < orbs; i++) {
    uv.x += x1*sin(x2*uv.y-stream);
    uv.y -= y1*cos(y2*uv.x+stream);
    float t = i * PI / orbs * 2.;
    float x = radius * tan(t+stream/10.);
    float y = radius * cos(t-stream/10.);
    vec2 position = vec2(x, y);
    vec3 color = cos(vec3(-2, 0, -1) * PI * 2. / 3. + PI * (float(i) / colorShift)) * 0.5 + 0.5;
    gl_FragColor += k_orb(uv, pow(volume, .5)*orbSize, position, color, contrast);
  }
}

#define BALLS 15.

void main() {
  float stream = stream / 3.;
  vec2 uv = k_uv();
  uv *= zoom;
  uv *= k_rotate2d(stream/-4.);
  // uv *=outer*sin(inner / 500.*dot(uv, uv) - stream/24.);
  uv = k_kale(uv, vec2(center), sides);
  uv *= k_rotate2d(stream/2.75);
  gl_FragColor = vec4(0);
  for (float i = 0.; i < BALLS; i++) {
    uv *= k_rotate2d(stream/-5.*PI/20.);
    float t = float(i) * PI / BALLS * (2. + 1.);
    float x = xOuter * sin(xInner * t - stream);
    float y = yOuter * cos(yOuter * t - stream/1.7);
    vec2 p = vec2(radius*x, radius*y);
    p /= pDiv * sin(PI * sin(uv.x/shape - stream/2.));
    vec3 col = cos(vec3(0, 1, -1) * PI * 2. / 3. + PI * (5. + float(i) / 5.)) * 0.5 + 0.5;
    gl_FragColor += vec4(pow(volume,.5)*ballSize / length(uv - p * 0.9) * col, contrast);
  }
  gl_FragColor.xyz = pow(gl_FragColor.xyz, vec3(contrast));
  gl_FragColor.w = 1.0;
}

#define orbs 20.

  vec2 kale(vec2 uv, vec2 offset, float sides) {
  float angle = atan(uv.y, uv.x);
  angle = ((angle / PI) + 1.0) * 0.5;
  angle = mod(angle, 1.0 / sides) * sides;
  angle = -abs(2.0 * angle - 1.0) + 1.0;
  angle = angle;
  float y = length(uv);
  angle = angle * (y);
  return vec2(angle, y) - offset;
} 

vec4 hue(vec4 color, float shift) {
  const vec4 kRGBToYPrime = vec4(0.299, 0.587, 0.114, 0.0);
  const vec4 kRGBToI = vec4(0.596, -0.275, -0.321, 0.0);
  const vec4 kRGBToQ = vec4(0.212, -0.523, 0.311, 0.0);
  const vec4 kYIQToR = vec4(1.0, 0.956, 0.621, 0.0);
  const vec4 kYIQToG = vec4(1.0, -0.272, -0.647, 0.0);
  const vec4 kYIQToB = vec4(1.0, -1.107, 1.704, 0.0);
  float YPrime = dot(color, kRGBToYPrime);
  float I = dot(color, kRGBToI);
  float Q = dot(color, kRGBToQ);
  float hue = atan(Q, I);
  float chroma = sqrt(I * I + Q * Q);
  hue += shift;
  Q = chroma * sin(hue);
  I = chroma * cos(hue);
  vec4 yIQ = vec4(YPrime, I, Q, 0.0);
  color.r = dot(yIQ, kYIQToR);
  color.g = dot(yIQ, kYIQToG);
  color.b = dot(yIQ, kYIQToB);
  return color;
}

vec3 palette(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {
  return a + b * cos(2. * PI * (c * t + d));
}

vec4 orb (vec2 uv, float size, vec2 position, vec3 color, float contrast) {
  return pow(vec4(size / length(uv + position) * color, 1.), vec4(contrast));
}

mat2 rotate (float angle) {
  return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

void main() {
  vec2 uv = k_uv();
  uv *= zoom;
  float dist = length(uv);
  uv *= abs(uv);
  uv *= rotate(dist/rotation + stream/50.);
  //uv /= dot(uv, uv);
  //uv = kale(uv, vec2(0), sides);
  //uv *= rotate(rotation*stream/10.);
  for (float i = 0.; i < orbs; i++) {
    uv.x += sinMul * sin(uv.y * yMul + stream*xSpeed) + cos(uv.y/yDivide-stream/2.);
    uv.y -= cosMul * cos(uv.x * xMul + stream*ySpeed) - sin(uv.x/xDivide-stream/2.);
    float t = i * PI / orbs * 2.;
    float x = radius * tan(t-stream/6.);
    float y = radius * sin(t+stream/8.);
    vec2 position = vec2(x, y);
    vec3 color = cos(vec3(-2, 0, -1) * PI * 2. / 3. + PI * (float(i) / colorShift)) * 0.5 + 0.5;
    gl_FragColor += orb(uv, volume * orbSize, position, 1.-color, contrast);
  }
}

