  angle = angle;
  float y = length(uv);
  angle = angle * (y);
  return vec2(angle, y) - offset;
} 
mat2 rotate2d(float _angle){
  return mat2(
    cos(_angle),
    -sin(_angle), 
    sin(_angle), 
    cos(_angle)
  );
}

float stepping(float t) {
  if (t < 0.) return -1. + pow(1. + t, 2.);
  else return 1. - pow(1. - t, 2.);
}
void main() {
  vec2 uv = k_uv().xy;
  gl_FragColor = vec4(0);
  uv = normalize(uv) * length(uv);
  vec2 uv2 = uv * zoom/5.;
  vec2 uv3 = uv * zoom/15.;
  uv = mix(uv2, uv3, abs(.1*sin(time/200.)));
  float dist = distance(uv, vec2(0));
  float thing = dist * .001*sin(shapeMultiplier*dot(uv2, uv3)/dist - stream/30.);
	if (warpTween) {
   	if (warp) {
    	uv = mix(uv, uv * uv, float(warpTweenProgress));
    } else {
      uv = mix(uv * uv, uv, float(warpTweenProgress));
    }
  } else if (warp) {
    uv = uv * uv;
  }
  vec2 _kale = kale(uv, vec2(0.), sides);
  if (kaleidoscopeTween) {
   	if (kaleidoscope) {
    	uv = mix(uv, _kale, float(kaleidoscopeTweenProgress));
    } else {
      uv = mix(_kale, uv, float(kaleidoscopeTweenProgress));
    } 
  } else if (kaleidoscope) {
    uv = kale(uv, vec2(0.), sides);
  }
  uv *= rotate2d(rotation * (dist - stream/200.));
  float _grid = (cos(uv.x * xMultiplier - stream/20.) - sin(uv.y * yMultiplier + stream/15.));
  uv /= colorSpread * thing  * _grid;
  uv*=dist;
  for (int i = 0; i < BALLS; i++) {
    float t = float(i) * PI / float(BALLS);
    vec2 p = vec2(sin(t), cos(t));
    p += cos(stream/3001. + float(i) * PI);
    vec3 col = cos(vec3(0, 1, -1) * PI * 2. / 3. + PI * (stream / 229. + float(i) / 5.)) * 0.5 + 0.5;
    gl_FragColor += vec4(ballSize  / length(uv + p * colorMultiplier) * col, 1.0);
  }
  gl_FragColor.xyz = glow * brightness * pow(gl_FragColor.xyz, vec3(contrast));
  gl_FragColor.w = 1.0;
  if (invert) gl_FragColor = 1. - gl_FragColor;
}
